<canvas id="canvas"></canvas><div class="hud">FORM <b id="h-mode">TREE</b><br>DEPTH <b id="h-depth">10</b><br>ANGLE <b id="h-angle">27</b><br><span class="sub">WIND</span> <b id="h-wind">0.30</b></div><?php $interactionHints=[['type'=>'drag','label'=>'wind'],['type'=>'click','label'=>'seed']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-mode="tree">TREE</button><button class="control-btn" data-mode="vein">VEIN</button><button class="control-btn" data-mode="root">ROOT</button></div></div><div><div class="slider-row"><span class="slider-label">DEPTH</span><input type="range" id="sl-depth" min="5" max="13" value="10"><span class="slider-value" id="sv-depth">10</span></div></div><div><div class="slider-row"><span class="slider-label">ANGLE</span><input type="range" id="sl-angle" min="12" max="48" value="27"><span class="slider-value" id="sv-angle">27</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-grow">GROW</button><button class="control-btn" id="btn-seed">SEED</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='tree',depth=10,ang=27,wind=.3,t=0,grow=true,seed=1;var hm=document.getElementById('h-mode'),hd=document.getElementById('h-depth'),ha=document.getElementById('h-angle'),hw=document.getElementById('h-wind'),sd=document.getElementById('sl-depth'),sa=document.getElementById('sl-angle'),vd=document.getElementById('sv-depth'),va=document.getElementById('sv-angle');function rnd(n){return Math.sin(n*127.1+seed*91.7)*.5+.5}function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function branch(x0,y0,len,a,d){if(d<=0||len<2)return;var g=grow?Math.min(1,.28+t*.28):1;var stage=(depth-d+1)/depth;if(stage>g)return;var sway=Math.sin(t+d*.7)*wind*.18, x1=x0+Math.cos(a+sway)*len, y1=y0+Math.sin(a+sway)*len, q=d/depth;x.strokeStyle=d%2?'rgba(0,245,212,'+(.2+q*.55)+')':'rgba(123,44,191,'+(.18+q*.45)+')';x.lineWidth=Math.max(1,len*.055)*D;x.beginPath();x.moveTo(x0,y0);x.lineTo(x1,y1);x.stroke();var spread=ang*Math.PI/180*(mode==='vein'?.65:1),sh=(rnd(d*3)-.5)*.22;if(mode==='root'){branch(x1,y1,len*.72,a+spread+sh,d-1);branch(x1,y1,len*.72,a-spread+sh,d-1);branch(x1,y1,len*.5,a+sh,d-2)}else{branch(x1,y1,len*.72,a-spread+sh,d-1);branch(x1,y1,len*.67,a+spread+sh,d-1);if(mode==='vein'&&d%3===0)branch(x1,y1,len*.54,a+sh,d-2)}}function draw(){if(grow)t+=.016;x.fillStyle='rgba(10,10,15,.2)';x.fillRect(0,0,W,H);x.globalCompositeOperation='lighter';var baseY=mode==='root'?H*.35:H*.88,dir=mode==='root'?Math.PI/2:-Math.PI/2;branch(W/2,baseY,Math.min(W,H)*.18,dir,depth);x.globalCompositeOperation='source-over';hw.textContent=wind.toFixed(2);requestAnimationFrame(draw)}function hud(){hm.textContent=mode.toUpperCase();hd.textContent=depth;vd.textContent=depth;ha.textContent=ang;va.textContent=ang;t=0}c.onpointerdown=e=>{seed++;t=0;if(typeof SFX!=='undefined')SFX.play('spawn',100)};c.onpointermove=e=>{if(e.buttons){wind=Math.max(0,Math.min(1,wind+(e.movementX||0)*.003));if(typeof SFX!=='undefined')SFX.play('move',120)}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(q=>q.classList.toggle('active',q===b));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});sd.oninput=()=>{depth=+sd.value;hud()};sa.oninput=()=>{ang=+sa.value;hud()};document.getElementById('btn-grow').onclick=e=>{grow=!grow;e.currentTarget.classList.toggle('active',grow);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-seed').onclick=()=>{seed++;t=0;if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>